import os, glob, math, csv, pickle
import numpy as np
from Bio import SeqIO, Align
from Bio.Data import IUPACData

AA3 = {k.upper():v for k,v in IUPACData.protein_letters_3to1.items()}
INP = '/task/input'

def load_seqs():
    return {r.id.split()[0]: str(r.seq) for r in SeqIO.parse(os.path.join(INP,'sequences.fasta'),'fasta')}

def load_xl():
    return list(csv.DictReader(open(os.path.join(INP,'crosslinks.csv'))))

NEIGH = []
for dx in (-1,0,1):
    for dy in (-1,0,1):
        for dz in (-1,0,1):
            if dx==dy==dz==0: continue
            NEIGH.append((dx,dy,dz,math.sqrt(dx*dx+dy*dy+dz*dz)))

def parse_model(fn):
    """Return atoms list: (chain, resnum, resname, atomname, x, y, z) and per-chain residue order."""
    atoms = []
    chains = {}
    with open(fn) as fh:
        for line in fh:
            if line[:6] in ('ATOM  ','HETATM'):
                rec = line[:6].strip()
                name = line[6:11].strip()
                altloc = line[16]
                resname = line[17:20].strip()
                ch = line[21]
                try:
                    resnum = int(line[22:26])
                except Exception:
                    continue
                icode = line[26]
                x = float(line[30:38]); y = float(line[38:46]); z = float(line[46:54])
                el = line[76:78].strip()
                if el.upper()=='H' or (not el and name[0].isalpha() and name.upper() in ('H','D')):
                    continue
                atoms.append((ch, resnum, icode, resname, name, x, y, z))
                d = chains.setdefault((ch,resnum,icode), {'resname':resname, 'atoms':[], 'xyz':[]})
                d['atoms'].append(name); d['xyz'].append((x,y,z))
    return atoms, chains

def chain_res_maps(fn, seqs):
    """Per chain: accession, ordered residue list [(resnum, resname, ca_xyz)], fullpos->(resnum,ca)."""
    atoms, chains = parse_model(fn)
    # order residues per chain by file order
    perchain = {}
    for (ch,resnum,icode), d in chains.items():
        if icode.strip() not in ('', ' '):
            pass  # keep insertion codes, they are distinct residues
        perchain.setdefault(ch, []).append((resnum, icode, d))
    out = {}
    aligner = Align.PairwiseAligner(mode='local', open_gap_score=-11, extend_gap_score=-1,
                                    match_score=2, mismatch_score=-1)
    for ch, lst in perchain.items():
        lst.sort(key=lambda t: t[0])
        s = ''.join(AA3.get(d['resname'].upper(),'X') for _,_,d in lst)
        best = None
        for acc, full in seqs.items():
            aln = aligner.align(full, s)[0]
            if best is None or aln.score > best[0]:
                best = (aln.score, acc, aln, full)
        score, acc, aln, full = best
        mism = 0
        posmap = {}
        covered = np.zeros(len(s), bool)
        for (fs,fe),(ms,me) in zip(*aln.aligned):
            covered[ms:me] = True
            for i in range(me-ms):
                fp = fs+i+1
                if full[fp-1] != s[ms+i]:
                    mism += 1
                posmap[fp] = lst[ms+i]
        fully = bool(covered.all())
        out[ch] = dict(acc=acc, mism=mism, fully=fully, score=float(score),
                       nres=len(lst), posmap=posmap)
    return out, atoms
